action_details.action_postfix:
// Physical nexus established - filing required
true result.la_has_nexus xdef
"Louisiana filing required: Physical presence (office, employees, or property in state)" job.audit_trail swap addto

// Economic nexus established per Wayfair - filing required
true result.la_has_nexus xdef
"Louisiana filing required: Economic nexus (exceeds $100,000 gross receipts threshold)" job.audit_trail swap addto

// Calculate Louisiana state additions
0.0 /la_additions xdef

// Common Louisiana additions:
// - Federal bond interest
// - Certain state tax refunds

result.la_us_interest_income 0.0 ne
{
  la_additions result.la_us_interest_income add /la_additions xdef
} if

la_additions result.la_state_additions xdef

// Calculate Louisiana state subtractions
0.0 /la_subtractions xdef

// Common Louisiana subtractions:
// - Standard deduction ($20,000 - NEW for 2025)
// - LA municipal interest
// - Qualified property expensing

// Apply Louisiana standard deduction (NEW for 2025 tax reform)
result.la_standard_deduction /la_subtractions xdef

result.la_municipal_interest 0.0 ne
{
  la_subtractions result.la_municipal_interest add /la_subtractions xdef
} if

la_subtractions result.la_state_subtractions xdef

"Louisiana additions: $" result.la_state_additions cvs strconcat ", subtractions: $" strconcat result.la_state_subtractions cvs strconcat job.audit_trail swap addto
"Louisiana standard deduction: $" result.la_standard_deduction cvs strconcat " (new for 2025)" strconcat job.audit_trail swap addto

// Calculate Louisiana taxable income // Federal taxable income apportioned to LA + additions - subtractions result.la_apportioned_income result.la_state_additions add result.la_state_subtractions sub 0.0 max result.la_taxable_income xdef
// Calculate Louisiana tax using flat rate: 5.5% (NEW for 2025) result.la_taxable_income result.la_corp_tax_rate mul /la_tax_before_credits xdef
// Subtract Louisiana state credits la_tax_before_credits result.la_state_credits sub 0.0 max result.la_tax_liability xdef
// Calculate refund or amount owed result.la_estimated_payments result.la_tax_liability sub result.la_refund_or_owed xdef
"Louisiana taxable income: $" result.la_taxable_income cvs strconcat job.audit_trail swap addto "Louisiana tax liability (5.5% flat rate, effective 2025): $" result.la_tax_liability cvs strconcat job.audit_trail swap addto
